export const MARKUP = "<!-- ArenaKit native side dock. Lives in its OWN webview (not injected into\n       arena.ai), docked to the right of the arena.ai webview. Decoupled from\n       the page DOM, so arena redesigns never break it. -->\n  <!-- Header = the reference app's panel top: model name (green; orange-yellow\n       when this turn's model differs from the conversation's first), the\n       per-turn status line, quota % + reset countdown with its bar, and the\n       browser back / forward / reload row. -->\n  <header class=\"ak-head\">\n    <div class=\"ak-head-row\">\n      <span class=\"ak-logo\" aria-hidden=\"true\"><svg viewBox=\"0 0 108 108\"><polygon fill=\"#3A82F7\" points=\"51.44,15.6 18.16,82.16 32.24,82.16 43.76,59.12 51.44,59.12\"/><polygon fill=\"#00E599\" points=\"56.56,15.6 56.56,59.12 64.24,59.12 75.76,82.16 89.84,82.16\"/><polygon fill=\"#FFFFFF\" points=\"39.92,66.8 68.08,66.8 73.2,77.04 34.8,77.04\"/><polygon fill=\"#FFFFFF\" points=\"54,10.48 57.2,19.44 54,28.4 50.8,19.44\"/></svg></span>\n      <div class=\"ak-head-main\">\n        <div id=\"ak-hud-model\" class=\"ak-hud-model\" data-known=\"false\" data-routed=\"false\">模型待确认</div>\n        <div id=\"ak-hud-status\" class=\"ak-hud-status\">等待会话流…</div>\n      </div>\n      <span class=\"ak-head-tools\"></span>\n    </div>\n    <div class=\"ak-hud-pulse-row\">\n      <span id=\"ak-hud-pulse\" class=\"ak-hud-pulse\">额度读取中…</span>\n      <button class=\"ak-link\" data-action=\"pulse-refresh\" title=\"额度接口每 60 秒读取一次；点此立即刷新\">刷新额度</button>\n    </div>\n    <div class=\"ak-bar\"><div id=\"ak-bar-fill\"></div></div>\n    <div class=\"ak-nav\">\n      <button class=\"ak-btn ak-btn-sm\" data-action=\"nav-back\">‹ 后退</button>\n      <button class=\"ak-btn ak-btn-sm\" data-action=\"nav-forward\">前进 ›</button>\n      <button class=\"ak-btn ak-btn-sm\" data-action=\"nav-reload\">刷新</button>\n    </div>\n  </header>\n\n  <!-- Module: server-side model (from the trace forensics pipeline) -->\n  <section class=\"ak-mod\" data-open=\"true\">\n    <div class=\"ak-mod-head\"><span>服务端模型</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <div id=\"ak-model\" class=\"ak-big\">—</div>\n      <div id=\"ak-model-sub\" class=\"ak-sub\">发一条消息后自动识别</div>\n      <div id=\"ak-session\" class=\"ak-sub ak-mono\"></div>\n      <div id=\"ak-turn-head\" class=\"ak-turn-head\"></div>\n      <div id=\"ak-turn-list\" class=\"ak-turns\"></div>\n    </div>\n  </section>\n\n  <!-- Module: Token / trace cost (observed labels only, never inferred) -->\n  <section class=\"ak-mod\" data-open=\"true\">\n    <div class=\"ak-mod-head\"><span>回复监控</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <div id=\"ak-monitor-head\" class=\"ak-sub\">监听回复流：空回复 / 报错 / 中断 / 停滞会自动标记到对应轮次。</div>\n      <div id=\"ak-monitor-list\" class=\"ak-list\"></div>\n    </div>\n  </section>\n\n  <section class=\"ak-mod\" data-open=\"true\">\n    <div class=\"ak-mod-head\"><span>使用额度（Token / 费用）</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <div class=\"ak-row\"><span id=\"ak-usage-ctx\" class=\"ak-sub\">当前会话</span><button class=\"ak-link\" data-action=\"usage-back\" hidden>返回当前会话</button></div>\n      <label class=\"ak-field\" id=\"ak-usage-pick-field\" hidden><span>查看运行</span>\n        <select id=\"ak-usage-pick\" class=\"ak-input\"></select>\n      </label>\n      <div id=\"ak-usage-meta\" class=\"ak-sub\"></div>\n      <div class=\"ak-kv\"><span class=\"ak-k\">本轮</span><span id=\"ak-usage-run\" class=\"ak-v\">未提供</span></div>\n      <div class=\"ak-kv\"><span class=\"ak-k\">本会话</span><span id=\"ak-usage-session\" class=\"ak-v\">未提供</span></div>\n      <div class=\"ak-kv\"><span class=\"ak-k\">累计</span><span id=\"ak-usage-total\" class=\"ak-v\">未提供</span></div>\n      <div id=\"ak-usage-calls\" class=\"ak-sub ak-calls\"></div>\n      <details class=\"ak-fold\"><summary>证据来源 <span id=\"ak-evidence-count\"></span></summary>\n        <div class=\"ak-sub\">只读来源：Trigger.dev run events → ai.streamText.doStream，按 runId + spanId 对齐，不混入其他运行。</div>\n        <div id=\"ak-evidence\"></div>\n      </details>\n      <div class=\"ak-btns\">\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"export-evidence\">导出证据 JSON</button>\n      </div>\n      <textarea id=\"ak-export\" class=\"ak-textarea\" hidden readonly></textarea>\n    </div>\n  </section>\n\n  <!-- Module: local conversation → model history (never leaves the device) -->\n  <section class=\"ak-mod\">\n    <div class=\"ak-mod-head\"><span>会话历史</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <input id=\"ak-history-q\" class=\"ak-input\" type=\"search\" placeholder=\"搜索标题 / 模型 / 会话 ID\" />\n      <div id=\"ak-history-list\" class=\"ak-list\"></div>\n      <button id=\"ak-history-more\" class=\"ak-btn ak-btn-sm ak-btn-wide\" hidden>加载更多</button>\n      <div class=\"ak-btns\">\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"history-export\">导出全部</button>\n        <button class=\"ak-btn ak-btn-sm ak-danger\" data-action=\"archive-current\" title=\"归档 Arena 上当前打开的对话（走 Arena 自带的归档菜单，可在归档中找回），并删除它的本地记录\">归档当前对话并删除记录</button>\n        <button class=\"ak-btn ak-btn-sm ak-danger\" data-action=\"history-clear\">清空历史</button>\n      </div>\n      <div id=\"ak-history-sub\" class=\"ak-sub\"></div>\n    </div>\n  </section>\n\n  <!-- Module: enhancement toggles + panels -->\n  <section class=\"ak-mod\">\n    <div class=\"ak-mod-head\"><span>自动探针（抽卡）</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <div class=\"ak-sub\">探针会新建对话并发送真实的算式消息（消耗额度），直到命中目标模型；命中的对话按「前缀 + 模型-序号」重命名。「自动抽卡」则不看目标：固定抽满轮数，每个对话按「前缀 + 模型」命名。</div>\n      <label class=\"ak-field\"><span>目标模型（逗号分隔；别名 opus5 / fable5 / gpt6，或 /正则/）</span>\n        <input id=\"ak-probe-targets\" class=\"ak-input\" type=\"text\" placeholder=\"opus5, fable5, gpt6\" autocomplete=\"off\" />\n      </label>\n      <div class=\"ak-inline\">\n        <label class=\"ak-field ak-field-sm\"><span>最多轮数</span><input id=\"ak-probe-rounds\" class=\"ak-input\" type=\"number\" min=\"1\" max=\"100\" step=\"1\" /></label>\n        <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-probe-findall\" /> 命中全部才停</label>\n        <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-probe-rename\" /> 命中后重命名</label>\n      </div>\n      <div class=\"ak-btns\">\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"probe-start\">开始探针</button>\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"draw-start\" title=\"按「最多轮数」连抽：每轮新建对话、发一条算式、识别模型；勾选「命中后重命名」时每个对话都按模型名重命名（不加序号），不看目标、不提前停\">自动抽卡</button>\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"probe-stop\" disabled>停止</button>\n      </div>\n      <div id=\"ak-probe-state\" class=\"ak-sub\"></div>\n      <pre id=\"ak-probe-log\" class=\"ak-log\" hidden></pre>\n    </div>\n  </section>\n\n  <section class=\"ak-mod\">\n    <div class=\"ak-mod-head\"><span>自动清理</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <div class=\"ak-sub\">归档侧栏中标题为「纯算式」的对话（探针残留，如 1+1=），并删除它们的本地记录。只走 Arena 自带的归档菜单，仅归档不删除；当前打开的对话和人工命名的对话不会被触碰。</div>\n      <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-cleanup-after\" /> 探针结束后自动清理</label>\n      <div class=\"ak-btns\">\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"cleanup-start\">立即清理</button>\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"cleanup-stop\" disabled>停止</button>\n      </div>\n      <div id=\"ak-cleanup-state\" class=\"ak-sub\"></div>\n    </div>\n  </section>\n\n  <section class=\"ak-mod\">\n    <div class=\"ak-mod-head\"><span>会话探针（当前对话）</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <div class=\"ak-sub\">在当前打开的对话里发送一条探针消息（消耗额度，不新建对话），用本轮 trace 识别「这一轮」实际应答的模型。留空则发送随机算式。</div>\n      <label class=\"ak-field\"><span>探针内容（可选）</span>\n        <input id=\"ak-quick-text\" class=\"ak-input\" type=\"text\" maxlength=\"8000\" placeholder=\"留空 = 随机算式，如 473×82=\" autocomplete=\"off\" />\n      </label>\n      <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-quick-rename\" /> 识别后按模型名重命名当前对话</label>\n      <div class=\"ak-btns\">\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"quick-send\">发送到当前对话</button>\n      </div>\n      <div id=\"ak-quick-state\" class=\"ak-sub\"></div>\n    </div>\n  </section>\n\n  <section class=\"ak-mod\">\n    <div class=\"ak-mod-head\"><span>重命名对话</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <label class=\"ak-field\"><span>标题前缀（可选）</span>\n        <input id=\"ak-rename-prefix\" class=\"ak-input\" type=\"text\" maxlength=\"40\" placeholder=\"例如 AK- 或 【探针】\" autocomplete=\"off\" />\n      </label>\n      <div id=\"ak-rename-preview\" class=\"ak-sub ak-mono\"></div>\n      <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-auto-rename\" /> 识别到模型后自动重命名当前对话</label>\n      <div class=\"ak-btns\">\n        <button class=\"ak-btn ak-btn-sm\" data-action=\"rename-now\">立即重命名为模型名</button>\n      </div>\n      <div id=\"ak-rename-status\" class=\"ak-sub\"></div>\n    </div>\n  </section>\n\n  <section class=\"ak-mod\" data-open=\"true\">\n    <div class=\"ak-mod-head\"><span>设置</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <label class=\"ak-field\"><span>主题</span>\n        <div class=\"ak-seg\" id=\"ak-theme\" role=\"group\" aria-label=\"主题\">\n          <button type=\"button\" data-theme-pick=\"auto\" aria-pressed=\"true\">跟随系统</button>\n          <button type=\"button\" data-theme-pick=\"light\" aria-pressed=\"false\">亮色</button>\n          <button type=\"button\" data-theme-pick=\"dark\" aria-pressed=\"false\">暗色</button>\n        </div>\n      </label>\n    </div>\n  </section>\n\n  <section class=\"ak-mod\" data-open=\"true\">\n    <div class=\"ak-mod-head\"><span>功能模块</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <button class=\"ak-btn\" data-action=\"manager\">模型筛选 / 管理面板</button>\n      <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-unlock-opus\" checked /> 解锁 Opus 全系</label>\n      <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-unlock-hidden\" /> 解锁隐藏 / 盲测模型</label>\n      <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-plus\" checked /> 排行榜性价比列</label>\n    </div>\n  </section>\n\n  <!-- Module: system-prompt injection (ENI) -->\n  <section class=\"ak-mod\">\n    <div class=\"ak-mod-head\"><span>提示词注入</span><span class=\"ak-chev\">▾</span></div>\n    <div class=\"ak-mod-body\">\n      <label class=\"ak-switch\"><input type=\"checkbox\" id=\"ak-eni-on\" /> 每新对话注入系统提示词</label>\n      <textarea id=\"ak-eni-text\" class=\"ak-textarea\" placeholder=\"在此输入系统提示词…\"></textarea>\n      <button class=\"ak-btn ak-btn-sm\" data-action=\"save-eni\">保存提示词</button>\n    </div>\n  </section>\n\n  <footer class=\"ak-foot\"><span id=\"ak-status\">就绪</span></footer>";
